SELECT c.interval_code, c.ingestion_source, DATE_FORMAT(c.open_time,'%Y-%m-%d %H:00') AS ksa_hour, COUNT(*) AS n, COUNT(DISTINCT c.symbol) AS symbols, MIN(c.updated_at) AS first_update_ksa, MAX(c.updated_at) AS last_update_ksa FROM candle c WHERE c.open_time BETWEEN '2026-10-10 16:00:00' AND '2026-10-11 10:00:00' AND c.closed = 1 AND c.close_transition_token IS NULL AND NOT EXISTS (SELECT 1 FROM candle_analysis_outcome o WHERE o.symbol = c.symbol AND o.interval_code = c.interval_code AND o.candle_open_time = c.open_time) AND NOT EXISTS (SELECT 1 FROM trade_signal s WHERE s.symbol = c.symbol AND s.interval_code = c.interval_code AND s.candle_open_time = c.open_time) GROUP BY c.interval_code, c.ingestion_source, ksa_hour ORDER BY ksa_hour, c.interval_code LIMIT 300